"""App setup. Owned by the lead (see CONTRACT.md); workers do not edit this file."""

from pathlib import Path

from fastapi import FastAPI, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from fastapi.staticfiles import StaticFiles
from starlette.exceptions import HTTPException

from app.routes import add, list as list_routes

FRONTEND_DIR = Path(__file__).resolve().parents[2] / "frontend"

app = FastAPI(title="Reading List Tracker")


def error_response(status: int, message: str) -> JSONResponse:
    return JSONResponse(status_code=status, content={"error": message, "status": status})


@app.exception_handler(RequestValidationError)
async def validation_error(request: Request, exc: RequestValidationError) -> JSONResponse:
    # Contract: FastAPI's default 422 becomes 400 with one readable message.
    first = exc.errors()[0] if exc.errors() else {}
    field = ".".join(str(p) for p in first.get("loc", []) if p not in ("body", "query", "path"))
    message = f"{field}: {first.get('msg', 'invalid input')}" if field else first.get("msg", "Invalid input")
    return error_response(400, message)


@app.exception_handler(HTTPException)
async def http_error(request: Request, exc: HTTPException) -> JSONResponse:
    # Contract: every error uses { "error": ..., "status": ... }.
    return error_response(exc.status_code, str(exc.detail))


@app.get("/health")
def health() -> dict:
    return {"ok": True}


app.include_router(add.router, prefix="/api")
app.include_router(list_routes.router, prefix="/api")

# Mounted last so it never shadows /api or /health.
app.mount("/", StaticFiles(directory=FRONTEND_DIR, html=True), name="frontend")
